INSERT INTO `testimonials` (`id`, `customer_name`, `rating`, `comment`, `device`, `raw_data`, `created_at`, `updated_at`) VALUES ('TESTI-1792723751464', 'Rian Pratama', 5, 'Servis ganti layar selesai dalam 40 menit di depan saya, hasil sangat presisi dan ada garansi resmi 90 hari. Mantap!', 'Samsung S22 Ultra', '{"id":"TESTI-1792723751464","date":"23 Okt 2026","name":"Rian Pratama","text":"Servis ganti layar selesai dalam 40 menit di depan saya, hasil sangat presisi dan ada garansi resmi 90 hari. Mantap!","device":"Samsung S22 Ultra","rating":5,"ticketId":"NGF-20261023-7182","verified":true}', '2026-11-04 11:30:11', '2026-11-04 11:30:31') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `testimonials` (`id`, `customer_name`, `rating`, `comment`, `device`, `raw_data`, `created_at`, `updated_at`) VALUES ('TESTI-20261023-0001', 'Dimas Prasetyo', 5, 'Layar iPhone tiba-tiba green screen blank setelah update iOS, sempat panik karena di tempat resmi divonis ganti whole unit jutaan. Di Ngalam Fix Pro berhasil diperbaiki jalurnya dalam 1,5 jam, TrueTone aktif normal dan data utuh. Luar biasa!', 'Apple iPhone 14 Pro Max', '{"id":"TESTI-20261023-0001","date":"23 Okt 2026","name":"Dimas Prasetyo","text":"Layar iPhone tiba-tiba green screen blank setelah update iOS, sempat panik karena di tempat resmi divonis ganti whole unit jutaan. Di Ngalam Fix Pro berhasil diperbaiki jalurnya dalam 1,5 jam, TrueTone aktif normal dan data utuh. Luar biasa!","device":"Apple iPhone 14 Pro Max","rating":5,"ticketId":"NGF-20261023-0001","verified":true}', '2026-11-04 11:30:11', '2026-11-04 11:30:31') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `testimonials` (`id`, `customer_name`, `rating`, `comment`, `device`, `raw_data`, `created_at`, `updated_at`) VALUES ('TESTI-20261022-0002', 'Siti Rahmawati', 5, 'Port cas kendor dan kamera belakang getar OIS saat buka Instagram. Dikerjakan langsung di depan mata dalam 45 menit selesai. Fast charging 45W lancar lagi dan kamera fokus mulus. Tempat servis HP paling jujur.', 'Samsung Galaxy S23 Ultra', '{"id":"TESTI-20261022-0002","date":"22 Okt 2026","name":"Siti Rahmawati","text":"Port cas kendor dan kamera belakang getar OIS saat buka Instagram. Dikerjakan langsung di depan mata dalam 45 menit selesai. Fast charging 45W lancar lagi dan kamera fokus mulus. Tempat servis HP paling jujur.","device":"Samsung Galaxy S23 Ultra","rating":5,"ticketId":"NGF-20261022-4389","verified":true}', '2026-11-04 11:30:11', '2026-11-04 11:30:31') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `testimonials` (`id`, `customer_name`, `rating`, `comment`, `device`, `raw_data`, `created_at`, `updated_at`) VALUES ('TESTI-20261021-0003', 'Budi Santoso', 5, 'HP Xiaomi anak saya tercebur ke ember air dan mati total. Dibawa ke Ngalam Fix Pro langsung ditangani ultrasonic cleaning dan ganti IC power. Nyala normal kembali tanpa kehilangan foto-foto keluarga. Recommended!', 'Xiaomi 13T & iPhone 13', '{"id":"TESTI-20261021-0003","date":"21 Okt 2026","name":"Budi Santoso","text":"HP Xiaomi anak saya tercebur ke ember air dan mati total. Dibawa ke Ngalam Fix Pro langsung ditangani ultrasonic cleaning dan ganti IC power. Nyala normal kembali tanpa kehilangan foto-foto keluarga. Recommended!","device":"Xiaomi 13T & iPhone 13","rating":5,"ticketId":"NGF-20261021-2472","verified":true}', '2026-11-04 11:30:12', '2026-11-04 11:30:31') ON DUPLICATE KEY UPDATE `id`=`id`;
