INSERT INTO `ads` (`id`, `title`, `headline`, `description`, `badge`, `image_url`, `target_url`, `cta_text`, `location`, `theme`, `active`, `views_count`, `clicks_count`, `raw_data`, `created_at`, `updated_at`) VALUES ('ad-baterai-90hari', 'Garansi Baterai 90 Hari', 'Ganti Baterai Original iPhone & Android — Garansi Resmi 90 Hari Penuh!', 'Baterai cepat drop atau kembung? Ganti di tempat dengan sel baterai Grade Original 100% Health, pengerjaan express 30–45 menit di meja transparan, dan jaminan perlindungan 90 hari tertulis resmi.', '⚡ GARANSI SPESIAL 90 HARI', 'images/promo-banner-1.jpg', '/pesan-servis?problem=baterai', 'Klaim Servis Baterai ↗', 'home_under_steps', 'gold', 1, 1420, 285, '{"id":"ad-baterai-90hari","badge":"⚡ GARANSI SPESIAL 90 HARI","theme":"gold","title":"Garansi Baterai 90 Hari","active":true,"ctaText":"Klaim Servis Baterai ↗","headline":"Ganti Baterai Original iPhone & Android — Garansi Resmi 90 Hari Penuh!","imageUrl":"images/promo-banner-1.jpg","location":"home_under_steps","createdAt":"2026-11-05T08:00:00.000Z","targetUrl":"/pesan-servis?problem=baterai","viewsCount":1420,"clicksCount":285,"description":"Baterai cepat drop atau kembung? Ganti di tempat dengan sel baterai Grade Original 100% Health, pengerjaan express 30–45 menit di meja transparan, dan jaminan perlindungan 90 hari tertulis resmi."}', '2026-11-05 08:47:42', '2026-11-05 08:47:42') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `ads` (`id`, `title`, `headline`, `description`, `badge`, `image_url`, `target_url`, `cta_text`, `location`, `theme`, `active`, `views_count`, `clicks_count`, `raw_data`, `created_at`, `updated_at`) VALUES ('ad-lcd-tempered', 'Paket Komplit Layar OLED + Bonus 9H', 'Ganti Layar Super Retina / OLED — Gratis Pasang Tempered Glass 9H Presisi!', 'Layar retak, blank hitam, atau touch error? Dapatkan diskon suku cadang hingga 30%, warna tajam 120Hz smooth, sensor responsif, plus bonus tempered glass 9H gratis langsung terpasang rapi.', '🔥 DISKON S/D 30% + BONUS 9H', 'images/promo-banner-tempered-glass.jpg', '/pesan-servis?problem=lcd&promo=FREEGLASS9H', 'Lihat Estimasi LCD ↗', 'home_under_steps', 'emerald', 1, 1190, 313, '{"id":"ad-lcd-tempered","badge":"🔥 DISKON S/D 30% + BONUS 9H","theme":"emerald","title":"Paket Komplit Layar OLED + Bonus 9H","active":true,"ctaText":"Lihat Estimasi LCD ↗","headline":"Ganti Layar Super Retina / OLED — Gratis Pasang Tempered Glass 9H Presisi!","imageUrl":"images/promo-banner-tempered-glass.jpg","location":"home_under_steps","createdAt":"2026-11-05T08:15:00.000Z","targetUrl":"/pesan-servis?problem=lcd&promo=FREEGLASS9H","viewsCount":1190,"clicksCount":312,"description":"Layar retak, blank hitam, atau touch error? Dapatkan diskon suku cadang hingga 30%, warna tajam 120Hz smooth, sensor responsif, plus bonus tempered glass 9H gratis langsung terpasang rapi."}', '2026-11-05 08:47:42', '2026-11-05 08:47:42') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `ads` (`id`, `title`, `headline`, `description`, `badge`, `image_url`, `target_url`, `cta_text`, `location`, `theme`, `active`, `views_count`, `clicks_count`, `raw_data`, `created_at`, `updated_at`) VALUES ('ad-member-vip-10', 'Tawaran Member VIP Diskon 5%', 'Gabung Member VIP Ngalam Fix Pro — Dapatkan Potongan Diskon 5% Servis HP!', 'Daftar akun gratis sekarang & nikmati potongan otomatis 5% seluruh servis smartphone (ganti LCD, baterai original, kamera & IC), pantau riwayat servis, klaim garansi online, dan nikmati prioritas pengerjaan di Meja 1.', '👑 TAWARAN MEMBER: DISKON 5%', 'images/spesialis-hp-banner.jpg', '/login?tab=register&promo=MEMBER10', 'Daftar Member & Klaim 5% ↗', 'home_under_steps', 'gold', 1, 3240, 893, '{"id":"ad-member-vip-10","badge":"👑 TAWARAN MEMBER: DISKON 5%","theme":"gold","title":"Tawaran Member VIP Diskon 5%","active":true,"ctaText":"Daftar Member & Klaim 5% ↗","headline":"Gabung Member VIP Ngalam Fix Pro — Dapatkan Potongan Diskon 5% Servis HP!","imageUrl":"images/spesialis-hp-banner.jpg","location":"home_under_steps","createdAt":"2026-11-05T09:00:00.000Z","targetUrl":"/akun-pelanggan?tab=register&promo=MEMBER10","viewsCount":3240,"clicksCount":890,"description":"Daftar akun gratis sekarang & nikmati potongan otomatis 5% seluruh servis smartphone (ganti LCD, baterai original, kamera & IC), pantau riwayat servis, klaim garansi online, dan nikmati prioritas pengerjaan di Meja 1."}', '2026-11-05 09:32:43', '2026-11-05 09:32:43') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `ads` (`id`, `title`, `headline`, `description`, `badge`, `image_url`, `target_url`, `cta_text`, `location`, `theme`, `active`, `views_count`, `clicks_count`, `raw_data`, `created_at`, `updated_at`) VALUES ('ad-mitra-afiliasi-10', 'Mitra Afiliasi Komisi 5%', 'Peluang Cuan Tanpa Modal: Jadi Mitra & Dapatkan Komisi 5% Tiap Rekomendasi Servis!', 'Punya teman, saudara, atau grup WA yang butuh servis HP? Cukup bagikan QR Code atau link referral Anda. Komisi 5% tunai otomatis cair ke rekening Anda setiap kali servis selesai!', '💰 CUAN 5% TANPA MODAL • MITRA RESMI', '', '/mitra?tab=register', 'Daftar Mitra Sekarang ↗', 'home_under_steps', 'emerald', 1, 3820, 1120, NULL, '2026-11-10 05:25:00', '2026-11-10 05:25:00') ON DUPLICATE KEY UPDATE `id`=`id`;
